"""Generate .github/workflows/study.yml (the stage jobs are repetitive; generating them avoids copy errors).
Run: python tools/make_workflow.py > .github/workflows/study.yml"""
CYCLES = ["smr", "n2_single", "n2_dual"]
VARIANTS = ["cvar_iso", "cvar_125", "worst_iso"]
MODEL_CASES = ["eff070", "eff080", "cool30", "cool40", "mita2", "mita5"]
ARCHIVE_CASES = ["alpha080", "alpha095", "pen150", "pen300"]
SET_CASES = ["kappa_x0.5", "kappa_x2", "fieldD", "fieldE_secondary"]

HEAD = """name: study

# Phases 5 to 10 of the LNG robust-design study. Generated by tools/make_workflow.py: edit the generator, not this file.
# Every unit reads the artifacts of its predecessors, writes a checkpoint and Parquet shards, and uploads them as artifacts.
# Dependent stages are chained with needs:. A final job merges everything, builds the results package and commits it to results/<run_id>.

on:
  workflow_dispatch:
    inputs:
      preset:
        description: "probe (tiny, measures time per evaluation, numbers are NOT results) or full"
        default: "probe"
        type: choice
        options: [probe, full]
      seed:
        description: "global seed"
        default: "20260101"

permissions:
  contents: write

env:
  PRESET: ${{ inputs.preset }}
  SEED: ${{ inputs.seed }}
  PYTHONUNBUFFERED: "1"
  LNG_FLASH_CACHE_MAX: "30000"

defaults:
  run:
    shell: bash

jobs:
  tests:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: "3.13"
          cache: pip
          cache-dependency-path: requirements.lock
      - name: Install pinned requirements
        run: |
          python -m pip install --upgrade pip
          pip install -r requirements.lock
          pip install -e . --no-deps
      - name: Full test suite
        run: python -m pytest -q
"""

STEPS = """      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: "3.13"
          cache: pip
          cache-dependency-path: requirements.lock
      - name: Install pinned requirements
        run: |
          python -m pip install --upgrade pip
          pip install -r requirements.lock
          pip install -e . --no-deps
"""


def download(pattern):
    return f"""      - uses: actions/download-artifact@v4
        with:
          pattern: {pattern}
          path: work
          merge-multiple: false
"""


def job(name, needs, matrix, key, cli, downloads, stage=None, parallel=20, always=False):
    mx = "\n".join(f"        {k}: {v}" for k, v in matrix.items())
    key_run = key
    s = f"""
  {name}:
    needs: [{', '.join(needs)}]
    runs-on: ubuntu-latest
    timeout-minutes: 330
    strategy:
      fail-fast: false
      max-parallel: {parallel}
      matrix:
{mx}
    steps:
{STEPS}"""
    for d in downloads:
        s += download(d)
    s += f"""      - name: Run unit
        run: |
          mkdir -p work
          python -m lng_robust.study.cli {cli} --preset "$PRESET" --seed "$SEED" --work work --workers 4
      - name: Evaluation counts
        if: always()
        run: python -m lng_robust.study.counts "work/unit-{key_run}" || true
      - name: Upload checkpoint and results
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: unit-{key_run}
          path: |
            work/unit-{key_run}
            !work/unit-{key_run}/evals-*.parquet
          retention-days: 90
          if-no-files-found: warn
      - name: Upload evaluation shards
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: shards-{key_run}
          path: work/unit-{key_run}/evals-*.parquet
          retention-days: 90
          if-no-files-found: ignore
"""
    return s


def main():
    out = [HEAD]
    mc = "${{ matrix.cycle }}"
    mv = "${{ matrix.variant }}"
    mk = "${{ matrix.case }}"
    cyc = {"cycle": "[" + ", ".join(CYCLES) + "]"}
    out.append(job("nominal", ["tests"], cyc, f"nominal-{mc}", f"nominal --cycle {mc}", []))
    out.append(job("sample", ["nominal"], cyc, f"sample-{mc}", f"sample --cycle {mc}", [f"unit-nominal-{mc}"]))
    out.append(job("surrogate", ["sample"], cyc, f"surrogate-{mc}", f"surrogate --cycle {mc}", [f"unit-sample-{mc}"]))
    cv = {"cycle": cyc["cycle"], "variant": "[" + ", ".join(VARIANTS) + "]"}
    prev = None
    for st in (1, 2, 3, 4, 5):
        dl = [f"unit-nominal-{mc}", f"unit-surrogate-{mc}"] + ([f"unit-robust-{mc}-{mv}-s{st-1}"] if st > 1 else [])
        out.append(job(f"robust{st}", ["surrogate"] + ([f"robust{st-1}"] if st > 1 else []), cv, f"robust-{mc}-{mv}-s{st}",
                       f"robust --cycle {mc} --variant {mv} --stage {st}", dl))
    rob = "unit-robust-" + mc + "-*"
    out.append(job("across", ["robust5"], cyc, f"across-{mc}", f"across --cycle {mc}",
                   [f"unit-nominal-{mc}", f"unit-surrogate-{mc}", rob]))
    rv = {"cycle": cyc["cycle"], "variant": "[nominal, robust]"}
    out.append(job("reversal", ["across"], rv, f"reversal-{mc}-{mv}", f"reversal --cycle {mc} --variant {mv}",
                   [f"unit-nominal-{mc}", f"unit-surrogate-{mc}", rob]))
    out.append(job("sobol", ["surrogate"], cyc, f"sobol-{mc}", f"sobol --cycle {mc}", [f"unit-nominal-{mc}", f"unit-surrogate-{mc}"]))
    out.append(job("sobol_pref", ["surrogate"], {"unit": "[pref]"}, "sobol_pref", "sobol_pref", ["unit-nominal-*", "unit-surrogate-*"]))
    sens_dl = [f"unit-nominal-{mc}", f"unit-surrogate-{mc}", rob, f"unit-across-{mc}"]
    out.append(job("sens_model", ["across"], {"cycle": cyc["cycle"], "case": "[" + ", ".join(MODEL_CASES) + "]"},
                   f"sens-{mc}-{mk}", f"sens --cycle {mc} --case {mk}", sens_dl))
    out.append(job("sens_archive", ["across"], {"cycle": cyc["cycle"], "case": "[" + ", ".join(ARCHIVE_CASES) + "]"},
                   f"sens-{mc}-{mk}", f"sens --cycle {mc} --case {mk}", sens_dl))
    out.append(job("sens_sets", ["across"], {"cycle": cyc["cycle"], "case": "[" + ", ".join(SET_CASES) + "]"},
                   f"sens-{mc}-{mk}", f"sens --cycle {mc} --case {mk}", sens_dl))
    out.append("""
  package:
    needs: [nominal, sample, surrogate, robust5, across, reversal, sobol, sobol_pref, sens_model, sens_archive, sens_sets]
    if: ${{ !cancelled() }}
    runs-on: ubuntu-latest
    timeout-minutes: 120
    steps:
""" + STEPS + """      - uses: actions/download-artifact@v4
        with:
          pattern: unit-*
          path: work
          merge-multiple: false
      - name: Build results package
        run: python -m lng_robust.study.package --work work --out results_package --run-id "${{ github.run_id }}" --preset "$PRESET"
      - uses: actions/upload-artifact@v4
        with:
          name: results-package-${{ github.run_id }}
          path: results_package
          retention-days: 90
      - name: Commit results to results/<run_id>
        run: |
          git config user.name "github-actions"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
          git checkout -b "results/${{ github.run_id }}"
          mkdir -p "results/${{ github.run_id }}"
          cp -r results_package/. "results/${{ github.run_id }}/"
          git add "results/${{ github.run_id }}"
          git commit -m "Results package for run ${{ github.run_id }} (preset ${PRESET})"
          git push origin "results/${{ github.run_id }}"
""")
    print("".join(out))


if __name__ == "__main__":
    main()
